<script setup lang="ts">
import {computed} from 'vue';
import type {ExecutionEvidence,ExecutionEvent} from '../executionTypes';
const props=defineProps<{evidence:ExecutionEvidence;event:ExecutionEvent;index:number}>();
const flow=computed(()=>props.evidence.plan.workflows?.find(f=>f.id===props.event.workflow?.workflowId));
const visited=computed(()=>new Set(props.evidence.report.events.slice(0,props.index+1).filter(e=>e.workflow?.instanceId===props.event.workflow?.instanceId&&e.workflow?.step).map(e=>e.workflow!.step!.nodeId)));
</script>
<template><section v-if="event.workflow&&flow" class="workflow-trace"><h4>{{flow.name}} · {{event.workflow.instanceId}}</h4><p><strong>{{event.workflow.status}}</strong> {{event.workflow.outcome}} · Current node: {{event.workflow.currentNode}} <span v-if="event.workflow.task">· Waiting task ID: <strong>{{event.workflow.task.id}}</strong></span></p><p v-if="event.workflow.event">Event {{event.workflow.event.id}}: {{event.workflow.event.status}} · {{event.workflow.event.message}}</p>
 <ol><li v-for="node in flow.lock.workflow.nodes" :key="node.id" :class="{current:(event.workflow.step?.nodeId||event.workflow.currentNode)===node.id,visited:visited.has(node.id)}"><strong>{{node.name}}</strong><small>{{node.kind}}{{node.task?' / '+node.task.kind:''}} · {{node.id}}</small><span v-if="node.branch">{{node.branch.variable}}: true → {{node.branch.then}} · false → {{node.branch.else}}</span><span v-else-if="node.next">Next → {{node.next}}</span><span v-if="node.command">Command {{node.command.command}} on {{node.command.owner}} · error → {{node.command.errorNext}}</span><span v-if="node.end">Outcome: {{node.end.outcome}}</span></li></ol>
 <details><summary>Workflow variables, outputs and current transition</summary><pre>{{JSON.stringify(event.workflow,null,2)}}</pre></details><p>Highlighted nodes show this saved token path. Unvisited branches have not executed. Workflow position, event receipts and task identities survive a modeled workflow restart.</p></section></template>
<style scoped>.workflow-trace{min-width:0}ol{display:grid;gap:8px;padding:0;list-style:none;max-width:720px}li{display:grid;gap:4px;padding:12px;border:1px solid #cbdce3;border-radius:8px;color:#647580;overflow-wrap:anywhere}.visited{background:#f0f8f4;color:#255542}.current{outline:2px solid #248568;background:#e1f3e9}small,span,p{font-size:12px;line-height:1.5}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:360px;overflow:auto;padding:12px;background:#f1f6f8}</style>
